import { Mesh, PlaneGeometry, Object3D, RepeatWrapping, LinearFilter } from 'three/webgpu';
import {
	uv,
	texture,
	mul,
	add,
	float,
	positionLocal,
	normalWorld,
	NodeMaterial
} from 'three/tsl';
import gsap from 'gsap';

/**
 * @typedef {import('three/webgpu').Object3D} THREEObject3D
 * @typedef {Object} NodeConfig
 * @property {{position: number[], rotation: number[], scale: number[]}} transform
 * @property {{imageUrl:string,depthMapUrl:string}} assets
 * @property {any[]} cinematicPrimitives
 * @property {any} textContent
 * @property {string} renderMode
 * @property {{event:string,effect:string}[]} interactions
 * @property {any} neighbors
 * @property {{atlas:number,rect:[number,number,number,number]}} atlasRegion
 *
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three/webgpu').Texture} textureLoader
 * @property {{[key:string]:(obj:THREEObject3D, params:any)=>void}} primitives
 * @property {(event:string)=>void} emit
 */

/**
 * Creates an ornamental divider node with a parallax‑displaced plane.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREEObject3D}
 */
export default function createNode (config, ctx) {
	// --------------------------------------------------------------------
	// Geometry – high‑tessellated plane
	// --------------------------------------------------------------------
	const geometry = new PlaneGeometry(1, 1, 64, 64);

	// --------------------------------------------------------------------
	// Textures
	// --------------------------------------------------------------------
	const colorTex = ctx.textureLoader(config.assets.imageUrl);
	const depthTex = ctx.textureLoader(config.assets.depthMapUrl);

	// Ensure textures repeat comfortably
	colorTex.wrapS = colorTex.wrapT = RepeatWrapping;
	depthTex.wrapS = depthTex.wrapT = RepeatWrapping;

	colorTex.minFilter = depthTex.minFilter = LinearFilter;

	// --------------------------------------------------------------------
	// Node‑based material
	// --------------------------------------------------------------------
	const uvNode = uv();

	const colorNode = texture(colorTex, uvNode);
	const depthNode = texture(depthTex, uvNode).r;

	// Subtle displacement amount (scene units)
	const displacementScale = float(0.08);

	const displacedPosition = add(
		positionLocal,
		mul(normalWorld, mul(depthNode, displacementScale))
	);

	const material = new NodeMaterial();
	material.colorNode = colorNode;
	material.positionNode = displacedPosition;
	material.transparent = true;
	material.side = 2; // DoubleSide

	// --------------------------------------------------------------------
	// Mesh assembly
	// --------------------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	mesh.castShadow = false;
	mesh.receiveShadow = false;

	// Apply transform from config (fallback defaults)
	const pos = config.position ?? [-1.25, -0.19999999999999996, 0];
	const rot = config.rotation ?? [0, 0, 0];
	const scl = config.scale ?? [1, 1, 1];

	mesh.position.set(pos[0], pos[1], pos[2]);
	mesh.rotation.set(rot[0], rot[1], rot[2]);
	mesh.scale.set(scl[0], scl[1], scl[2]);

	// --------------------------------------------------------------------
	// Parallax primitive (if available)
	// --------------------------------------------------------------------
	if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
		try {
			ctx.primitives['parallax-scroll'](mesh, {});
		} catch (e) {
			// Silently ignore if primitive fails
		}
	}

	// --------------------------------------------------------------------
	// Interaction handling
	// --------------------------------------------------------------------
	const cleanupStack = [];

	const hoverRiseTween = { current: null };
	const hoverEnter = () => {
		if (hoverRiseTween.current) return;
		hoverRiseTween.current = gsap.to(mesh.position, {
			y: mesh.position.y + 0.15,
			duration: 0.7,
			ease: 'power3.out',
			onComplete: () => (hoverRiseTween.current = null)
		});
		cleanupStack.push(() => hoverRiseTween.current && hoverRiseTween.current.kill());
	};

	const hoverLeave = () => {
		if (!hoverRiseTween.current) return;
		hoverRiseTween.current.reverse();
		hoverRiseTween.current = null;
	};

	const clickEmit = () => {
		if (ctx.emit) ctx.emit('hub-features.select');
	};

	// Populate handlers object as required by the runtime
	mesh.userData.handlers = {
		hover: hoverEnter,
		hoverout: hoverLeave,
		click: clickEmit
	};

	// --------------------------------------------------------------------
	// Cleanup logic
	// --------------------------------------------------------------------
	mesh.userData.cleanup = () => {
		// Kill any GSAP timelines registered in cleanupStack
		cleanupStack.forEach((fn) => {
			try {
				fn();
			} catch (e) {
				/* ignore */
			}
		});
		// Dispose geometry & material
		geometry.dispose();
		if (material.dispose) material.dispose();
	};

	// --------------------------------------------------------------------
	// Return the fully assembled node
	// --------------------------------------------------------------------
	const root = new Object3D();
	root.add(mesh);
	// Propagate handlers and cleanup to the root for convenience
	root.userData.handlers = mesh.userData.handlers;
	root.userData.cleanup = mesh.userData.cleanup;

	return root;
}
